<div class="gamification-widget-list"><?php foreach ($teams as $team): ?><article><div class="gamification-widget-team-heading"><?php if (!empty($team['logo_path'])): ?><img src="<?php echo utf8_htmlentities(url($team['logo_path'])) ?>" alt="" loading="lazy" /><?php endif ?><h3><a href="<?php echo url('teams/'.$team['team_id'].'/'.$team['slug']) ?>"><?php echo utf8_htmlentities($team['title']) ?></a></h3></div><ul><?php foreach ($team['members'] as $member): ?><li><?php echo utf8_htmlentities($member['display_name']) ?><?php if ($member['role']): ?> <small><?php echo utf8_htmlentities($member['role']) ?></small><?php endif ?></li><?php endforeach ?></ul></article><?php endforeach ?></div>
